from pyspark.sql import functions as F


def solve(forecasts):
    perth = F.to_utc_timestamp("valid_for", "Australia/Perth")
    return forecasts.select(
        "forecast_id",
        "station_id",
        perth.alias("perth_valid_for"),
        F.date_format(perth, "dd/MM hh:mm").alias("perth_label"),
    )
